<?php $b=$data['booking']; if(!$b): ?><div class="empty-state"><h1>Rendez-vous introuvable</h1><a class="primary-btn" href="<?= APP_URL ?>/index.php">Accueil</a></div><?php else: ?><section class="appointment-page reveal"><div class="back-row"><a href="<?= APP_URL ?>/index.php">←</a><span>Mon rendez-vous</span></div><div class="confirmed-card"><div class="success-orbit"><span>✓</span></div><p class="eyebrow">RENDEZ-VOUS STYLT</p><h1>Rendez-vous confirmé.</h1><p class="muted">Garde cette page pour retrouver rapidement les informations essentielles.</p><div class="appointment-pro"><img src="<?= APP_URL.'/'.e($b['photo_path']) ?>" alt=""><div><strong><?= e($b['professional_name']) ?></strong><span><?= $b['verified'] ? 'Professionnel vérifié · ' : '' ?>★ <?= number_format((float)$b['rating'],1) ?></span></div></div><div class="appointment-grid"><div><span>Date</span><strong><?= date('d/m/Y',strtotime($b['appointment_date'])) ?></strong></div><div><span>Heure</span><strong><?= e(substr($b['appointment_time'],0,5)) ?></strong></div><div><span>Coiffeur</span><strong><?= e($b['professional_name']) ?></strong></div><div><span>Prestation</span><strong><?= e($b['service_name']) ?></strong></div><div><span>Mode</span><strong><?= e($b['mode']) ?></strong></div><div><span>Zone</span><strong><?= e($b['zone']) ?></strong></div></div><div class="booking-total"><span>Total convenu</span><strong><?= number_format((float)$b['price'],0,' ',' ') ?> FCFA</strong></div><div class="appointment-actions"><button class="secondary-btn" onclick="window.print()">Imprimer / PDF</button><a class="primary-btn" href="<?= APP_URL ?>/index.php">Retour à l'accueil</a></div></div></section><?php endif; ?>
